    from dvc.dvcfile import PIPELINE_FILE, PIPELINE_LOCK, is_valid_filename
    from dvc.exceptions import DvcException

    if not target:
        return None, None

    # NOTE: the stage name may contain colons itself (e.g. stage names
    # generated from a `foreach` over a list of dict values), so we can
    # only treat the part before a colon as a path if it looks like
    # an actual dvc file (or is empty, meaning the default file).
    path, name = target, None
    for index, char in enumerate(target):
